const NINTH_ORIGINAL_URL=new URL("../../../../../model-comparison-metrics/verify-final-dist.mjs",import.meta.url);
import {ninthLeaf,ninthHash,ninthEntry,ninthQuestion,ninthReferenceQuestion,ninthReferenceEntry,ninthIncludes,ninthFragment,ninthSubstantiveIncludes,ninthSourceText,ninthSourceHash,ninthRegistryBefore,ninthEntryHash,ninthKeyIncludes,ninthKeyHash,ninthKeyFragment,ninthKeyQuestion} from '../../../../verify-reference.mjs';
import {appendProviderQuestion} from '../seventh-reconciliation/verify-dependencies.mjs';
import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';
const home=path.dirname(fileURLToPath(NINTH_ORIGINAL_URL));const read=n=>JSON.parse(fs.readFileSync(path.join(home,n),'utf8')),sha=s=>crypto.createHash('sha256').update(s).digest('hex'),plain=s=>s.replace(/<[^>]*>/g,'').replaceAll('&gt;','>').replaceAll('&lt;','<').replaceAll('&amp;','&');
export const names=['guarded replacement leaves are actually applied','four appended answers and exact composite dependency exist','old complete objects and identity are preserved','four canonical answer bodies retain exact old prefixes','all 108 original blocks have substantive or archive destinations','all 25 variants remain traceable with exact specialist originals','formula and boundary contracts are present','all newly emitted internal links resolve','AUC and denominator teaching examples are numerically valid','artifact has no code implementation or fabricated empirical claims'];
export function verify(dist){const errors=[],checks=[];let entries=[];for(const f of fs.readdirSync(path.join(dist,'data/chapters')).filter(f=>f.endsWith('.json')))entries.push(...JSON.parse(fs.readFileSync(path.join(dist,'data/chapters',f),'utf8')).entries);const E=new Map(entries.map(e=>[e.id,e]));assert.equal(E.size,entries.length);const get=k=>{let [eid,q]=k.split('#');let e=E.get(eid);assert.ok(e,'missing entry '+eid);if(q===undefined)return e;let it=e.items?.find((it,i)=>String(it.id??i)===q);assert.ok(it,'missing question '+k);return it;};
const rs=read('records.json').records,app=read('append-manifest.json').additions,dep=read('composite-dependency.json'),baseline=read('identity-baseline.json'),map=read('preservation-map.json'),vs=read('variant-map.json'),archive=read('out-of-scope-original-archive.json'),sections=read('sections.json');const run=(name,fn)=>{try{fn();checks.push({name,passed:true});}catch(e){checks.push({name,passed:false,error:e.message});errors.push(name+': '+e.message);}};
run(names[0],()=>{assert.equal(rs.length,6);for(const r of rs){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);assert.notEqual(r.before,r.after);let value=E.get(r.entryId);for(const k of r.path)value=value[k];assert.equal(value,r.after,r.stableReviewKey+' '+r.path.join('.'));}});
run(names[1],()=>{assert.equal(app.length,4);assert.equal(sha(JSON.stringify(dep.expectedItem)),dep.expectedItemSha256);assert.equal(sha(dep.expectedItem.a),dep.expectedAnswerSha256);assert.deepEqual(E.get(dep.entryId).items[dep.index],dep.expectedItem);for(const a of app){assert.equal(sha(a.expectedItem.a),a.afterSha256);assert.equal(sha(JSON.stringify(a.expectedItem)),a.expectedItemSha256);assert.deepEqual(E.get(a.entryId).items[a.expectedIndex],a.expectedItem,a.questionId);}assert.equal(E.get('ai-模型与评测-2').items.length,14);assert.equal(E.get('ai-模型与评测-2').number,'14 问');assert.equal(E.get('own-theory-math').items.length,7);});
run(names[2],()=>{const raw=fs.readFileSync(path.join(home,'sixth-composition-reconciliation.json'));assert.equal(sha(raw),'2be41f2a9bd4073142fa9c17ebcce39e9d7157948f3c0aabcce6f2318104db6a');const composition=JSON.parse(raw);assert.equal(composition.schemaVersion,1);assert.equal(composition.sameBatchParallelRecords.length,4);assert.deepEqual(composition.sameBatchParallelRecords.map(r=>[r.entryId,r.path]),[['ai-模型与评测-3',['items',6,'a']],['ai-模型与评测-3',['items',6,'lead']],['ai-模型与评测-3',['items',7,'a']],['ai-模型与评测-3',['items',7,'lead']]]);for(const [name,h]of Object.entries(composition.sourceFiles))assert.equal(sha(fs.readFileSync(path.join(home,name))),h);const prior=composition.priorWorkflowRecord;assert.deepEqual([prior.entryId,prior.path],['ai-模型与评测-2',['items',5,'a']]);assert.equal(prior.after,prior.before+composition.priorWorkflowExactAppendHtml);assert.ok(composition.priorWorkflowExactAppendHtml.length>0);for(const r of [prior,...composition.sameBatchParallelRecords]){assert.equal(sha(r.before),r.beforeSha256);assert.equal(sha(r.after),r.afterSha256);}for(const e of baseline.entries){let expected=structuredClone(e);for(const r of [prior,...composition.sameBatchParallelRecords].filter(r=>r.entryId===e.id)){let x=expected;for(const k of r.path.slice(0,-1))x=x[k];assert.equal(x[r.path.at(-1)],r.before,'exact previous whole-object leaf');x[r.path.at(-1)]=r.after;}for(const r of rs.filter(r=>r.entryId===e.id)){let x=expected;for(const k of r.path.slice(0,-1))x=x[k];x[r.path.at(-1)]=r.after;}if(e.id===dep.entryId)expected.items.push(dep.expectedItem);for(const a of app.filter(a=>a.entryId===e.id))expected.items.push(a.expectedItem);if(e.id==='ai-模型与评测-2')expected.number='13 问';assert.deepEqual(E.get(e.id),appendProviderQuestion(expected),e.id+' full object changed outside approved leaves/appends');}});
run(names[3],()=>{let pref=rs.filter(r=>r.mode==='exact-old-prefix-plus-append');assert.equal(pref.length,4);for(let r of pref){assert.ok(r.after.startsWith(r.before),r.stableReviewKey);assert.ok(r.after.length>r.before.length);assert.ok(get(r.stableReviewKey).a.startsWith(r.before));}const main=get('ai-模型与评测-2#1');for(const anchor of ['add-own-practice-236d0589a993293f','add-own-theory-alignment-e43e398ee1','add-own-theory-inference-e43e398ee1'])assert.ok(main.a.includes('id="'+anchor+'"'));});
run(names[4],()=>{let old=rs.find(r=>r.entryId==='ai-模型与评测-2'&&r.path.at(-1)==='a').before;assert.equal(sha(old),map.beforeSha256);const src=[...old.matchAll(/<(p|h[1-6]|li|th|td|summary)\b[^>]*>[\s\S]*?<\/\1>/g)];assert.equal(src.length,108);assert.equal(map.blocks.length,108);for(let [i,b] of map.blocks.entries()){assert.equal(b.sourceBlockIndex,i);assert.equal(b.sourceHtml,src[i][0]);assert.equal(sha(b.sourceHtml),b.sourceSha256);assert.equal(old.slice(...b.sourceSpanCodeUnits),b.sourceHtml);if(b.archiveId!==null){let a=archive.records.find(x=>x.sourceBlockIndex===b.archiveId);assert.ok(a);assert.equal(a.originalHtml,b.sourceHtml);assert.equal(sha(a.originalHtml),a.sha256);}assert.ok(b.destinations.length||b.disposition==='archive');for(let d of b.destinations){assert.equal(sha(d.html),d.sha256);assert.ok(/<p\b/.test(d.html),'not substantive '+d.section);let body=get(d.stableReviewKey).a;if(d.fragments){for(const f of d.fragments)assert.ok(ninthKeyIncludes(E,d.stableReviewKey,f),d.stableReviewKey+' fragment missing');}else assert.ok(ninthKeyIncludes(E,d.stableReviewKey,d.html),d.stableReviewKey+' '+d.section+' missing');}}});
run(names[5],()=>{assert.equal(vs.variants.length,25);assert.equal(vs.retainedPublicCount,22);assert.equal(vs.archivedCount,3);let old=archive.originalQuestionObject.a;assert.equal(sha(old),archive.originalAnswerSha256);for(let v of vs.variants){assert.ok(old.includes(v.originalHtml));assert.equal(sha(v.originalHtml),v.sha256);if(v.disposition==='archive'){let a=archive.records.find(x=>x.sourceBlockIndex===v.archiveId);assert.equal(a.originalHtml,v.originalHtml);}else assert.ok(plain(get('ai-模型与评测-2#1').a).includes(v.originalText),v.originalText);}assert.equal(archive.records.length,9);});
run(names[6],()=>{for(let [key,terms] of Object.entries({'own-theory-math#q-model-auc-gauc':['0.5I(sₚ=sₙ)','p·N_before+0.5pn','(|P||N|)','GAUC=Σ(w_g AUC_g)/Σw_g','0.99','F1=2PR/(P+R)','不可定义'],'ai-模型与评测-2#q-model-paired-statistics-ab':['McNemar','b+c','cluster bootstrap','n≈2(z_{1−α/2}+z_{1−β})²σ²/δ²','Y′=Y−θ(X−E[X])','SRM','switchback','一个百分点','无条件高风险'],'ai-模型与评测-2#q-model-generation-metrics':['sqrt(BLEU×chrF1)','β=1','句 BLEU','否定','多参考'],'ai-模型与评测-2#q-model-pairwise-preference':['E_A=1/(1+10^((R_B−R_A)/400))','R_A新=R_A+K(S_A−E_A)','Bradley–Terry','0.5×平局数','成对图若断开']})){let a=get(key).a;for(const t of terms)assert.ok(a.includes(t),key+' missing '+t);}});
run(names[7],()=>{const bodies=rs.filter(r=>r.path.at(-1)==='a').map(r=>r.mode==='exact-old-prefix-plus-append'?r.after.slice(r.before.length):r.after).concat(app.map(a=>a.expectedItem.a));for(let body of bodies)for(let m of body.matchAll(/href="#\/e\/([^"#]+)"/g)){let [e,q]=m[1].split('/').map(decodeURIComponent);get(e+(q===undefined?'':'#'+q));}});
run(names[8],()=>{function auc(xs){let p=xs.filter(x=>x[1]===1),n=xs.filter(x=>x[1]===0);if(!p.length||!n.length)return null;return p.reduce((sum,x)=>sum+n.reduce((a,y)=>a+(x[0]>y[0]?1:x[0]===y[0]?0.5:0),0),0)/(p.length*n.length);}let A=Array.from({length:100},(_,i)=>[.9,i<99?1:0]),B=Array.from({length:100},(_,i)=>[.1,i<1?1:0]);assert.equal(auc(A),.5);assert.equal(auc(B),.5);assert.equal(auc([...A,...B]),.99);assert.equal(auc([[1,1]]),null);assert.equal(auc([]),null);const f1=(tp,fp,fn)=>2*tp+fp+fn===0?null:2*tp/(2*tp+fp+fn);assert.equal(f1(0,0,0),null);assert.equal(f1(1,1,1),.5);assert.ok(Math.abs((.86-.85)*100-1)<1e-10);assert.equal(Math.sqrt(0*.8),0);});
run(names[9],()=>{let publicNew=rs.map(r=>r.mode==='exact-old-prefix-plus-append'?r.after.slice(r.before.length):r.after).concat(app.map(a=>a.expectedItem.a)).join('');assert.ok(!/<(?:pre|code)\b/.test(publicNew));assert.ok(!/我们已实现召回率从85%到86%|线上提升了17%|我们达到了95%/.test(publicNew));assert.ok(get('ai-模型与评测-2#q-model-paired-statistics-ab').a.includes('数字只是题设目标'));assert.ok(get('ai-模型与评测-2#1').a.includes('不补造数据'));});
return {passed:errors.length===0,checks,errors,mode:'actual-dist-only',dist:path.resolve(dist),overlay:false,siteWrites:0,readOnlyFixtureHashes:Object.fromEntries(['records.json','append-manifest.json','composite-dependency.json','identity-baseline.json','preservation-map.json','variant-map.json','out-of-scope-original-archive.json','sections.json'].map(n=>[n,sha(fs.readFileSync(path.join(home,n)))]))};}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){let i=process.argv.indexOf('--dist');assert.ok(i>=0,'--dist required');try{const result=verify(path.resolve(process.argv[i+1]));console.log(JSON.stringify(result,null,2));if(!result.passed)process.exitCode=1;}catch(e){console.error(e.stack);process.exitCode=1;}}
